class Solution {
public:
    int countComponents(vector<int>& nums, int threshold) {
        unordered_map<int, int> parent;
        auto find = [&](auto& self, int i) -> int {
            if (!parent.contains(i)) parent[i] = i;
            return parent[i] == i ? i : (parent[i] = self(self, parent[i]));
        };
        auto unite = [&](int i, int j) {
            int rootI = find(find, i);
            int rootJ = find(find, j);
            if (rootI != rootJ) parent[rootI] = rootJ;
        };

        for (int num : nums) {
            if (num <= threshold) {
                for (int multiple = 2 * num; multiple <= threshold; multiple += num) {
                    unite(num, multiple);
                }
            }
        }

        unordered_set<int> roots;
        for (int num : nums) {
            roots.insert(find(find, num));
        }
        return roots.size();
    }
};

class Solution {
    public int countComponents(int[] nums, int threshold) {
        Map<Integer, Integer> parent = new HashMap<>();
        for (int num : nums) {
            if (num <= threshold) {
                for (int multiple = 2 * num; multiple <= threshold; multiple += num) {
                    union(parent, num, multiple);
                }
            }
        }
        Set<Integer> roots = new HashSet<>();
        for (int num : nums) {
            roots.add(find(parent, num));
        }
        return roots.size();
    }

    private int find(Map<Integer, Integer> parent, int i) {
        parent.putIfAbsent(i, i);
        if (parent.get(i) == i) return i;
        int root = find(parent, parent.get(i));
        parent.put(i, root);
        return root;
    }

    private void union(Map<Integer, Integer> parent, int i, int j) {
        int rootI = find(parent, i);
        int rootJ = find(parent, j);
        if (rootI != rootJ) parent.put(rootI, rootJ);
    }
}

var countComponents = function(nums, threshold) {
    const parent = new Map();
    const find = (i) => {
        if (!parent.has(i)) parent.set(i, i);
        if (parent.get(i) === i) return i;
        const root = find(parent.get(i));
        parent.set(i, root);
        return root;
    };
    const union = (i, j) => {
        const rootI = find(i);
        const rootJ = find(j);
        if (rootI !== rootJ) parent.set(rootI, rootJ);
    };

    for (const num of nums) {
        if (num <= threshold) {
            for (let multiple = 2 * num; multiple <= threshold; multiple += num) {
                union(num, multiple);
            }
        }
    }

    const roots = new Set();
    for (const num of nums) {
        roots.add(find(num));
    }
    return roots.size;
};
